/**
 * Server-backed voice (spec §11–§13): spoken replies generated by the configured speech service and played through
 * Web Audio, and voice input recorded with MediaRecorder and transcribed by the configured service. Both fall back to
 * the browser engines when the server has no speech service configured.
 *
 * Lip-sync: while server audio plays, an AnalyserNode measures the loudness of the audio that is actually playing and
 * drives the mouth from it (≈ every animation frame). This is an amplitude approximation — it follows pauses and
 * emphasis in the real audio but does not reproduce individual phonemes.
 */
import type { ListenCallbacks } from './recognition';
import type { TTSHooks } from './tts';

export interface SpeechOut {
  readonly supported: boolean; readonly speaking: boolean; hooks: TTSHooks; rate: number; voiceURI: string | null; boundaryEvents: boolean;
  enqueue(text: string, style: import('../../shared/schema').SpeakingStyle): void; stop(): void; voices(): SpeechSynthesisVoice[];
  pause?(): void; resume?(): void;
  /** how the mouth is driven right now (shown in Status) */
  readonly lipSync?: string;
}
export interface SpeechIn { readonly supported: boolean; listening: boolean; start(cb: ListenCallbacks, lang?: string): void; stop(): void; abort(): void; readonly kind?: string }

/** Loudness (RMS of a time-domain frame, 0…1) → mouth openness 0…1 with a noise floor and soft knee. */
export function levelToMouth(rms: number): number {
  const v = Math.max(0, rms - 0.015) * 7;
  return Math.min(1, v / (1 + v * 0.35));
}
export function rmsOf(buf: Uint8Array): number { let s = 0; for (let i = 0; i < buf.length; i++) { const x = (buf[i] - 128) / 128; s += x * x; } return Math.sqrt(s / buf.length); }

type Item = { text: string; audio: Promise<Blob> };

export class ServerSpeechOutput implements SpeechOut {
  readonly supported = typeof window !== 'undefined' && typeof Audio !== 'undefined' && typeof URL !== 'undefined' && typeof URL.createObjectURL === 'function';
  hooks: TTSHooks = {}; rate = 1; voiceURI: string | null = null; boundaryEvents = false; lipSync = 'audio level (approximation)';
  private queue: Item[] = []; private busy = false; private gen = 0; private started = false;
  private ctl = new AbortController(); private current: HTMLAudioElement | null = null; private url: string | null = null;
  private ctx: AudioContext | null = null; private analyser: AnalyserNode | null = null; private raf = 0; private pulse: ReturnType<typeof setInterval> | null = null;
  /** called when one sentence could not be generated or played; the router speaks it with the fallback voice */
  onFailure: (message: string, text: string) => void = () => {};
  constructor(private base = '', private fetchImpl: typeof fetch = (...a) => fetch(...a)) {}
  voices() { return []; }
  get speaking() { return this.busy || this.queue.length > 0; }

  enqueue(text: string) {
    const t = text.trim(); if (!t || !this.supported) return;
    for (const chunk of splitForTts(t)) this.queue.push({ text: chunk, audio: this.fetchAudio(chunk) });  // prefetch keeps order and removes gaps
    if (!this.busy) void this.next(this.gen);
  }
  private async fetchAudio(text: string): Promise<Blob> {
    const r = await this.fetchImpl(`${this.base}/api/tts`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ text }), signal: this.ctl.signal });
    if (!r.ok) { const j = await r.json().catch(() => ({})) as { error?: string }; throw new Error(j.error ?? `Speech service error (HTTP ${r.status})`); }
    return r.blob();
  }
  private async next(g: number): Promise<void> {
    if (g !== this.gen) return;
    const item = this.queue.shift();
    if (!item) { this.finish(); return; }
    this.busy = true;
    let blob: Blob;
    try { blob = await item.audio; } catch (e) { if (g !== this.gen) return; this.onFailure((e as Error).message, item.text); return this.next(g); }
    if (g !== this.gen) return;
    this.cleanupAudio();
    this.url = URL.createObjectURL(blob);
    const a = new Audio(this.url); this.current = a; a.playbackRate = this.rate;
    const done = (failed?: string) => { if (g !== this.gen || this.current !== a) return; this.stopLevels(); this.cleanupAudio(); if (failed) this.onFailure(failed, item.text); void this.next(g); };
    a.onended = () => done(); a.onerror = () => done('The speech audio could not be played.');
    a.onplaying = () => { if (g !== this.gen) return; if (!this.started) { this.started = true; this.hooks.onStart?.(); } this.startLevels(a); };
    a.onpause = () => this.stopLevels();
    try { await a.play(); } catch (e) { done(`Audio playback was blocked: ${(e as Error).message}`); }
  }
  private finish() { const was = this.busy || this.started; this.busy = false; this.started = false; this.stopLevels(); this.cleanupAudio(); if (was) this.hooks.onIdle?.(); }
  private startLevels(a: HTMLAudioElement) {
    this.stopLevels();
    try {
      if (!this.ctx) { const AC = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext; this.ctx = new AC(); }
      void this.ctx.resume();
      const src = this.ctx.createMediaElementSource(a); const an = this.ctx.createAnalyser(); an.fftSize = 512;
      src.connect(an); an.connect(this.ctx.destination); this.analyser = an;
      const buf = new Uint8Array(an.fftSize);
      const tick = () => { if (!this.analyser) return; this.analyser.getByteTimeDomainData(buf); this.hooks.onLevel?.(levelToMouth(rmsOf(buf))); this.raf = requestAnimationFrame(tick); };
      this.lipSync = 'audio level (approximation)'; this.raf = requestAnimationFrame(tick);
    } catch {
      // Web Audio unavailable: keep speaking, move the mouth on a timer while the audio plays (honestly labelled)
      this.lipSync = 'timed while audio plays (no audio analysis available)';
      this.pulse = setInterval(() => { if (this.current && !this.current.paused) this.hooks.onLevel?.(0.55); }, 160);
    }
  }
  private stopLevels() { if (this.raf) cancelAnimationFrame(this.raf); this.raf = 0; if (this.pulse) clearInterval(this.pulse); this.pulse = null; this.analyser?.disconnect(); this.analyser = null; this.hooks.onLevel?.(0); }
  private cleanupAudio() { const a = this.current; this.current = null; if (a) { a.onended = a.onerror = a.onplaying = a.onpause = null; try { a.pause(); } catch { /* gone */ } a.removeAttribute('src'); } if (this.url) { URL.revokeObjectURL(this.url); this.url = null; } }
  pause() { this.current?.pause(); }
  resume() { void this.current?.play().catch(() => {}); }
  stop() {
    this.gen++; this.ctl.abort(); this.ctl = new AbortController(); this.queue = [];
    const was = this.busy || this.started; this.busy = false; this.started = false;
    this.stopLevels(); this.cleanupAudio(); if (was) this.hooks.onIdle?.();
  }
}

/** Keeps each speech request small enough for fast first audio and for the server's 1200-character limit. */
export function splitForTts(text: string, max = 600): string[] {
  if (text.length <= max) return [text];
  const out: string[] = []; let rest = text;
  while (rest.length > max) { const cut = Math.max(rest.lastIndexOf('. ', max), rest.lastIndexOf(', ', max), rest.lastIndexOf(' ', max)); const at = cut > max * 0.4 ? cut + 1 : max; out.push(rest.slice(0, at).trim()); rest = rest.slice(at); }
  if (rest.trim()) out.push(rest.trim());
  return out;
}

const MIC_ERR: Record<string, [string, string]> = {
  NotAllowedError: ['Microphone permission was denied. Allow it in the app or browser settings, or type instead.', 'not-allowed'],
  SecurityError: ['Microphone permission was denied. Allow it in the app or browser settings, or type instead.', 'not-allowed'],
  NotFoundError: ['No microphone was found.', 'audio-capture'], NotReadableError: ['The microphone is being used by another program.', 'audio-capture'],
};

/**
 * Records one utterance and sends it to the server for transcription. End of speech = about 1.2 s of quiet after
 * speech was heard; it also stops after 30 s, or after 8 s if nothing was said. Only one final transcript is delivered.
 */
export class ServerSpeechInput implements SpeechIn {
  readonly supported = typeof navigator !== 'undefined' && !!navigator.mediaDevices?.getUserMedia && typeof window !== 'undefined' && typeof (window as unknown as { MediaRecorder?: unknown }).MediaRecorder === 'function';
  readonly kind = 'server';
  listening = false;
  private rec: MediaRecorder | null = null; private stream: MediaStream | null = null; private ctx: AudioContext | null = null;
  private timer: ReturnType<typeof setInterval> | null = null; private session = 0; private ctl: AbortController | null = null;
  constructor(private base = '', private fetchImpl: typeof fetch = (...a) => fetch(...a)) {}
  start(cb: ListenCallbacks) {
    this.abort(); const s = ++this.session;
    if (!this.supported) { cb.onError('Voice recording is not supported here, so please type instead.', 'unsupported'); return; }
    void navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } }).then((stream) => {
      if (s !== this.session) { stream.getTracks().forEach((t) => t.stop()); return; }
      this.stream = stream;
      const chunks: Blob[] = [];
      const rec = new MediaRecorder(stream); this.rec = rec;
      rec.ondataavailable = (e) => { if (e.data.size) chunks.push(e.data); };
      let heard = false;
      rec.onstop = () => {
        this.release();
        if (s !== this.session) return;               // aborted: nothing is sent
        this.listening = false;
        if (!heard) { cb.onState(false); cb.onError('I didn\'t hear anything.', 'no-speech'); return; }
        const blob = new Blob(chunks, { type: rec.mimeType || 'audio/webm' });
        cb.onTranscribing?.(); cb.onInterim('Transcribing…');
        this.ctl = new AbortController();
        void this.fetchImpl(`${this.base}/api/transcribe`, { method: 'POST', headers: { 'content-type': blob.type || 'audio/webm' }, body: blob, signal: this.ctl.signal })
          .then(async (r) => { const j = await r.json().catch(() => ({})) as { text?: string; error?: string; code?: string }; if (s !== this.session) return; if (!r.ok) { cb.onError(j.error ?? `Transcription failed (HTTP ${r.status}).`, j.code ?? 'transcription'); return; } const t = (j.text ?? '').trim(); if (!t) cb.onError('I didn\'t catch any words.', 'no-speech'); else cb.onFinal(t); })
          .catch((e) => { if (s === this.session && (e as Error).name !== 'AbortError') cb.onError(`Could not reach the transcription service: ${(e as Error).message}`, 'network'); });
      };
      // end-of-speech detection from the microphone level
      try {
        const AC = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
        this.ctx = new AC(); const an = this.ctx.createAnalyser(); an.fftSize = 1024; this.ctx.createMediaStreamSource(stream).connect(an);
        const buf = new Uint8Array(an.fftSize); const t0 = Date.now(); let lastLoud = 0;
        this.timer = setInterval(() => {
          an.getByteTimeDomainData(buf); const lvl = rmsOf(buf); const now = Date.now();
          if (lvl > 0.035) { heard = true; lastLoud = now; }
          if ((heard && now - lastLoud > 1200) || now - t0 > 30000 || (!heard && now - t0 > 8000)) this.stop();
        }, 100);
      } catch { heard = true; this.timer = setTimeout(() => this.stop(), 8000) as unknown as ReturnType<typeof setInterval>; }
      rec.start(250); this.listening = true; cb.onState(true);
    }).catch((e: Error) => {
      if (s !== this.session) return;
      const [msg, code] = MIC_ERR[e.name] ?? [`Could not start the microphone: ${e.message}`, 'start'];
      cb.onError(msg, code);
    });
  }
  stop() { if (this.rec && this.rec.state !== 'inactive') this.rec.stop(); }
  abort() { this.session++; this.ctl?.abort(); this.ctl = null; if (this.rec && this.rec.state !== 'inactive') this.rec.stop(); this.release(); this.listening = false; }
  private release() { if (this.timer) clearInterval(this.timer); this.timer = null; this.stream?.getTracks().forEach((t) => t.stop()); this.stream = null; void this.ctx?.close().catch(() => {}); this.ctx = null; this.rec = null; }
}
